var UserConnection = Get<UserConnection>("UserConnection");
string storeId = Get<string>("StoreId");
string deviceItems = Get<string>("DeviceItems");
Guid lineDetailId = Get<Guid>("LineDetailId");
string lineDetailIds = Get<string>("LineDetailIds");
bool isSendRequest = Get<bool>("SendRequest");

var service = new DMSService(UserConnection);
var checkStockService = new CheckStock(UserConnection);

try {
	if(!string.IsNullOrEmpty(storeId) && !string.IsNullOrEmpty(deviceItems)) {
		
		List<string> deviceItemList = deviceItems.Split(',').ToList();
		var param = checkStockService.GetParam(storeId, deviceItemList);
		Set("Request", param.ToString());

		if(isSendRequest) {
			var result = service.CheckStock(param).GetAwaiter().GetResult();
			Set("Response", result.ToString());
		}
	
	} else if(lineDetailId != Guid.Empty) { // line detail
		
		var param = checkStockService.GetParam(lineDetailId);
		Set("Request", param.ToString());

		if(isSendRequest) {
			var result = service.CheckStock(param).GetAwaiter().GetResult();
			Set("Response", result.ToString());
		}

	} else if(!string.IsNullOrEmpty(lineDetailIds)) {
		
		List<Guid> lineDetailIdList = lineDetailIds
			.Split(',')
			.Select(item => Guid.Parse(item))
			.ToList();
		var param = checkStockService.GetParamList(lineDetailIdList);
		Set("Request", JsonConvert.SerializeObject(param));

		if(isSendRequest) {
			var result = service.CheckStockBatch(lineDetailIdList).GetAwaiter().GetResult();
			Set("Response", JsonConvert.SerializeObject(result));
		}

	}
} catch (Exception e) {
	Set("Message", e.Message);
}

return true;
